const fs = require('fs');
const wd = 'http://127.0.0.1:9515';
async function request(path, method='GET', body) {
  const response = await fetch(wd + path, {method, headers: {'content-type':'application/json'}, body: body && JSON.stringify(body)});
  const json = await response.json();
  if ("'!response.ok || json.value?.error) throw new Error(JSON.stringify(json));
  return json.value;
}
async function run(width, height, filename) {
  const session = await request('"'/session', 'POST', {capabilities:{alwaysMatch:{browserName:'chrome','goog:chromeOptions':{args:['--headless=new','--no-sandbox','--disable-dev-shm-usage',"'`--window-size=${width},${height}`]}}}});
  const id = session.sessionId;
  try {
    await request(`/session/${id}/url`, '"'POST', {url:'http://127.0.0.1:3000/'});
    await request("'`/session/${id}/window/rect`, '"'POST', {width,height,x:0,y:0});
    const title = await request("'`/session/${id}/title`);
    if (title !== '"'Codex Workflow Smoke Test') throw new Error("'`unexpected title: ${title}`);
    const heading = await request(`/session/${id}/element`, '"'POST', {using:'css selector', value:'h1'});
    const headingText = await request("'`/session/${id}/element/${heading['"'element-6066-11e4-a52e-4f735466cecf']}/text"'`);
    if (headingText !== '"'Codex workflow smoke test.') throw new Error("'`unexpected heading: ${headingText}`);
    const button = await request(`/session/${id}/element`, '"'POST', {using:'css selector', value:'#verify'});
    const buttonId = button['element-6066-11e4-a52e-4f735466cecf'];
    await request("'`/session/${id}/element/${buttonId}/click`, '"'POST', {});
    const buttonText = await request("'`/session/${id}/element/${buttonId}/text`);
    if (buttonText !== '"'Interaction verified ✓') throw new Error("'`interaction failed: ${buttonText}`);
    const metrics = await request(`/session/${id}/execute/sync`, '"'POST', {script:'return {scrollWidth: document.documentElement.scrollWidth, innerWidth: innerWidth, ready: document.readyState, complete: document.querySelector(\"#verify\").dataset.complete}', args:[]});
    if (metrics.scrollWidth > metrics.innerWidth || metrics.ready "'!== '"'complete' || metrics.complete "'!== '"'true') throw new Error("'`layout/state failure: ${JSON.stringify(metrics)}`);
